window.MG_LAZY_DATA["data/lazy/owner-courses/v11-ionq-forte-3906bd576aced4df.json"]={sha256:"3906bd576aced4df451f53935f6648de3671a1efa32ea9448629465f2c5beda5",value:{"id":"v11-ionq-forte","title":"IonQ Forte 光學位址量子核心","titleEn":"IonQ Forte optically addressed quantum core","category":"computing","subcategory":"quantum-ion","subcategoryTitle":"離子陷阱量子系統","subcategoryTitleEn":"Trapped-ion quantum systems","learningTrack":"quantum","learningSubdiscipline":"quantum-ion","learningTags":["quantum","quantum-ion","ionq-forte"],"kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"curriculumVersion":11,"stepCount":12,"estimatedMinutes":420,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"sourceIds":["v11x-forte","v11x-iontech"],"stages":[{"id":"v11-ionq-forte-v11-stage1","order":1,"title":"系統邊界與基本原理","titleEn":"System boundaries and principles","description":"在IonQ Forte 光學位址量子核心案例中比較Forte離子鏈模態與AOD光束選址，各完成分析及驗證。","descriptionEn":"Analyze and validate forte ion-chain modes and aod beam addressing within the IonQ Forte optically addressed quantum core case.","steps":[{"id":"v11-ionq-forte-v11-01","order":1,"sequence":1,"title":"離子陷阱與模態：架構分析","titleEn":"Ion traps and modes: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":[],"objective":"針對Forte離子鏈模態提出可反駁的離子陷阱與模態模型與驗證紀錄。","objectiveEn":"Produce a falsifiable ion traps and modes model and evidence record for forte ion-chain modes.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識Forte離子鏈模態。電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。 建立離子陷阱與模態的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。區分內部態、運動模態及環境噪聲三個子系統。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify forte ion-chain modes in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Electric fields confine charged ions; collective motion mediates some entangling gates. Draw the inputs, states, outputs and boundaries of ion traps and modes, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Separate internal states, motional modes and environmental noise. Record units, undisclosed parameters and model breakdown conditions.","observation":"區分內部態、運動模態及環境噪聲三個子系統。","observationEn":"Separate internal states, motional modes and environmental noise.","failure":"常見誤判：離子內部態與運動模態是同一個變數。","failureEn":"Common misconception: Internal states and motional modes are the same variable.","check":"提交Forte離子鏈模態的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for forte ion-chain modes.","knowledge":[{"id":"v11-ionq-forte-v11-01-k1","title":"離子陷阱與模態","titleEn":"Ion traps and modes","text":"電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。 本課架構對應：Forte離子鏈模態","textEn":"Electric fields confine charged ions; collective motion mediates some entangling gates. Course architecture correspondence: Forte ion-chain modes","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-01-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"區分內部態、運動模態及環境噪聲三個子系統。 應逐項保留基準與不確定度；離子內部態與運動模態是同一個變數。 是本單元要排除的誤解。","textEn":"Separate internal states, motional modes and environmental noise. Retain each reference and uncertainty; reject the misconception: Internal states and motional modes are the same variable.","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-01-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 42 個獨立且相同錯誤率 p=0.0010 的事件，無錯誤機率 (1−p)^42=0.958850。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 42 independent events with equal p=0.0010: no-error probability (1−p)^42=0.958850. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-forte","v11x-iontech"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Forte離子鏈模態的「離子陷阱與模態」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for ion traps and modes in forte ion-chain modes?","options":["電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。","離子內部態與運動模態是同一個變數。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Electric fields confine charged ions; collective motion mediates some entangling gates.","Internal states and motional modes are the same variable.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。 區分內部態、運動模態及環境噪聲三個子系統。","explanationEn":"Electric fields confine charged ions; collective motion mediates some entangling gates. Separate internal states, motional modes and environmental noise."}},{"id":"v11-ionq-forte-v11-02","order":2,"sequence":2,"title":"離子陷阱與模態：證據驗證","titleEn":"Ion traps and modes: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-01"],"objective":"針對Forte離子鏈模態提出可反駁的離子陷阱與模態模型與驗證紀錄。","objectiveEn":"Produce a falsifiable ion traps and modes model and evidence record for forte ion-chain modes.","instruction":"沿用前一步「離子陷阱與模態」模型，檢查Forte離子鏈模態的兩個假想案例。區分內部態、運動模態及環境噪聲三個子系統。 先訂可接受誤差，再比較預測與獨立計算；區分電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous ion traps and modes model to inspect two hypothetical cases involving forte ion-chain modes. Separate internal states, motional modes and environmental noise. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Electric fields confine charged ions; collective motion mediates some entangling gates.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"區分內部態、運動模態及環境噪聲三個子系統。","observationEn":"Separate internal states, motional modes and environmental noise.","failure":"常見誤判：離子內部態與運動模態是同一個變數。","failureEn":"Common misconception: Internal states and motional modes are the same variable.","check":"提交Forte離子鏈模態的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for forte ion-chain modes.","knowledge":[{"id":"v11-ionq-forte-v11-02-k1","title":"離子陷阱與模態","titleEn":"Ion traps and modes","text":"電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。 本課架構對應：Forte離子鏈模態","textEn":"Electric fields confine charged ions; collective motion mediates some entangling gates. Course architecture correspondence: Forte ion-chain modes","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-02-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"區分內部態、運動模態及環境噪聲三個子系統。 應逐項保留基準與不確定度；離子內部態與運動模態是同一個變數。 是本單元要排除的誤解。","textEn":"Separate internal states, motional modes and environmental noise. Retain each reference and uncertainty; reject the misconception: Internal states and motional modes are the same variable.","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-02-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 42 個獨立且相同錯誤率 p=0.0010 的事件，無錯誤機率 (1−p)^42=0.958850。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 42 independent events with equal p=0.0010: no-error probability (1−p)^42=0.958850. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-forte","v11x-iontech"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就Forte離子鏈模態的「離子陷阱與模態」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for ion traps and modes in forte ion-chain modes?","options":["離子內部態與運動模態是同一個變數。","區分內部態、運動模態及環境噪聲三個子系統。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Internal states and motional modes are the same variable.","Separate internal states, motional modes and environmental noise.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"電場侷限帶電離子；集體運動模態提供部分糾纏閘的中介。 區分內部態、運動模態及環境噪聲三個子系統。","explanationEn":"Electric fields confine charged ions; collective motion mediates some entangling gates. Separate internal states, motional modes and environmental noise."}},{"id":"v11-ionq-forte-v11-03","order":3,"sequence":3,"title":"雷射位址與空間串擾：架構分析","titleEn":"Laser addressing and spatial crosstalk: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-02"],"objective":"針對AOD光束選址提出可反駁的雷射位址與空間串擾模型與驗證紀錄。","objectiveEn":"Produce a falsifiable laser addressing and spatial crosstalk model and evidence record for aod beam addressing.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識AOD光束選址。光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。 建立雷射位址與空間串擾的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。用位址矩陣比較目標響應與非目標響應。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify aod beam addressing in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Beam addressing localizes control, but sidelobes and drift can affect neighbors. Draw the inputs, states, outputs and boundaries of laser addressing and spatial crosstalk, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare intended and unintended responses in an addressing matrix. Record units, undisclosed parameters and model breakdown conditions.","observation":"用位址矩陣比較目標響應與非目標響應。","observationEn":"Compare intended and unintended responses in an addressing matrix.","failure":"常見誤判：可軟體選址表示沒有光學串擾。","failureEn":"Common misconception: Software addressing implies zero optical crosstalk.","check":"提交AOD光束選址的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for aod beam addressing.","knowledge":[{"id":"v11-ionq-forte-v11-03-k1","title":"雷射位址與空間串擾","titleEn":"Laser addressing and spatial crosstalk","text":"光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。 本課架構對應：AOD光束選址","textEn":"Beam addressing localizes control, but sidelobes and drift can affect neighbors. Course architecture correspondence: AOD beam addressing","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-03-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用位址矩陣比較目標響應與非目標響應。 應逐項保留基準與不確定度；可軟體選址表示沒有光學串擾。 是本單元要排除的誤解。","textEn":"Compare intended and unintended responses in an addressing matrix. Retain each reference and uncertainty; reject the misconception: Software addressing implies zero optical crosstalk.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就AOD光束選址的「雷射位址與空間串擾」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for laser addressing and spatial crosstalk in aod beam addressing?","options":["可軟體選址表示沒有光學串擾。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。"],"optionsEn":["Software addressing implies zero optical crosstalk.","Equal case averages rule out spatial, temporal and model errors.","Beam addressing localizes control, but sidelobes and drift can affect neighbors."],"answer":2,"explanation":"光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。 用位址矩陣比較目標響應與非目標響應。","explanationEn":"Beam addressing localizes control, but sidelobes and drift can affect neighbors. Compare intended and unintended responses in an addressing matrix."}},{"id":"v11-ionq-forte-v11-04","order":4,"sequence":4,"title":"雷射位址與空間串擾：證據驗證","titleEn":"Laser addressing and spatial crosstalk: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-03"],"objective":"針對AOD光束選址提出可反駁的雷射位址與空間串擾模型與驗證紀錄。","objectiveEn":"Produce a falsifiable laser addressing and spatial crosstalk model and evidence record for aod beam addressing.","instruction":"沿用前一步「雷射位址與空間串擾」模型，檢查AOD光束選址的兩個假想案例。用位址矩陣比較目標響應與非目標響應。 先訂可接受誤差，再比較預測與獨立計算；區分光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous laser addressing and spatial crosstalk model to inspect two hypothetical cases involving aod beam addressing. Compare intended and unintended responses in an addressing matrix. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Beam addressing localizes control, but sidelobes and drift can affect neighbors.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"用位址矩陣比較目標響應與非目標響應。","observationEn":"Compare intended and unintended responses in an addressing matrix.","failure":"常見誤判：可軟體選址表示沒有光學串擾。","failureEn":"Common misconception: Software addressing implies zero optical crosstalk.","check":"提交AOD光束選址的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for aod beam addressing.","knowledge":[{"id":"v11-ionq-forte-v11-04-k1","title":"雷射位址與空間串擾","titleEn":"Laser addressing and spatial crosstalk","text":"光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。 本課架構對應：AOD光束選址","textEn":"Beam addressing localizes control, but sidelobes and drift can affect neighbors. Course architecture correspondence: AOD beam addressing","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-04-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"用位址矩陣比較目標響應與非目標響應。 應逐項保留基準與不確定度；可軟體選址表示沒有光學串擾。 是本單元要排除的誤解。","textEn":"Compare intended and unintended responses in an addressing matrix. Retain each reference and uncertainty; reject the misconception: Software addressing implies zero optical crosstalk.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就AOD光束選址的「雷射位址與空間串擾」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for laser addressing and spatial crosstalk in aod beam addressing?","options":["用位址矩陣比較目標響應與非目標響應。","可軟體選址表示沒有光學串擾。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Compare intended and unintended responses in an addressing matrix.","Software addressing implies zero optical crosstalk.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"光束位址將控制侷限到目標離子，但光學旁瓣及漂移可影響鄰近離子。 用位址矩陣比較目標響應與非目標響應。","explanationEn":"Beam addressing localizes control, but sidelobes and drift can affect neighbors. Compare intended and unintended responses in an addressing matrix."}}]},{"id":"v11-ionq-forte-v11-stage2","order":2,"title":"功能架構與量化模型","titleEn":"Functional architecture and quantitative models","description":"在IonQ Forte 光學位址量子核心案例中比較激光糾纏與閉合軌跡與全連通與共享光路，各完成分析及驗證。","descriptionEn":"Analyze and validate laser entanglement and closed paths and connectivity and shared optics within the IonQ Forte optically addressed quantum core case.","steps":[{"id":"v11-ionq-forte-v11-05","order":1,"sequence":5,"title":"運動介導的糾纏：架構分析","titleEn":"Motion-mediated entanglement: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-04"],"objective":"針對激光糾纏與閉合軌跡提出可反駁的運動介導的糾纏模型與驗證紀錄。","objectiveEn":"Produce a falsifiable motion-mediated entanglement model and evidence record for laser entanglement and closed paths.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識激光糾纏與閉合軌跡。兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。 建立運動介導的糾纏的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較閉合與未閉合假想相空間軌跡。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify laser entanglement and closed paths in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information. Draw the inputs, states, outputs and boundaries of motion-mediated entanglement, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare closed and unclosed hypothetical phase-space paths. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較閉合與未閉合假想相空間軌跡。","observationEn":"Compare closed and unclosed hypothetical phase-space paths.","failure":"常見誤判：只要任意時刻有糾纏就代表閘完成。","failureEn":"Common misconception: Entanglement at any intermediate time proves a completed gate.","check":"提交激光糾纏與閉合軌跡的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for laser entanglement and closed paths.","knowledge":[{"id":"v11-ionq-forte-v11-05-k1","title":"運動介導的糾纏","titleEn":"Motion-mediated entanglement","text":"兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。 本課架構對應：激光糾纏與閉合軌跡","textEn":"Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information. Course architecture correspondence: Laser entanglement and closed paths","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-05-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較閉合與未閉合假想相空間軌跡。 應逐項保留基準與不確定度；只要任意時刻有糾纏就代表閘完成。 是本單元要排除的誤解。","textEn":"Compare closed and unclosed hypothetical phase-space paths. Retain each reference and uncertainty; reject the misconception: Entanglement at any intermediate time proves a completed gate.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就激光糾纏與閉合軌跡的「運動介導的糾纏」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for motion-mediated entanglement in laser entanglement and closed paths?","options":["只要任意時刻有糾纏就代表閘完成。","兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Entanglement at any intermediate time proves a completed gate.","Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。 比較閉合與未閉合假想相空間軌跡。","explanationEn":"Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information. Compare closed and unclosed hypothetical phase-space paths."}},{"id":"v11-ionq-forte-v11-06","order":2,"sequence":6,"title":"運動介導的糾纏：證據驗證","titleEn":"Motion-mediated entanglement: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-05"],"objective":"針對激光糾纏與閉合軌跡提出可反駁的運動介導的糾纏模型與驗證紀錄。","objectiveEn":"Produce a falsifiable motion-mediated entanglement model and evidence record for laser entanglement and closed paths.","instruction":"沿用前一步「運動介導的糾纏」模型，檢查激光糾纏與閉合軌跡的兩個假想案例。比較閉合與未閉合假想相空間軌跡。 先訂可接受誤差，再比較預測與獨立計算；區分兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous motion-mediated entanglement model to inspect two hypothetical cases involving laser entanglement and closed paths. Compare closed and unclosed hypothetical phase-space paths. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較閉合與未閉合假想相空間軌跡。","observationEn":"Compare closed and unclosed hypothetical phase-space paths.","failure":"常見誤判：只要任意時刻有糾纏就代表閘完成。","failureEn":"Common misconception: Entanglement at any intermediate time proves a completed gate.","check":"提交激光糾纏與閉合軌跡的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for laser entanglement and closed paths.","knowledge":[{"id":"v11-ionq-forte-v11-06-k1","title":"運動介導的糾纏","titleEn":"Motion-mediated entanglement","text":"兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。 本課架構對應：激光糾纏與閉合軌跡","textEn":"Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information. Course architecture correspondence: Laser entanglement and closed paths","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-06-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較閉合與未閉合假想相空間軌跡。 應逐項保留基準與不確定度；只要任意時刻有糾纏就代表閘完成。 是本單元要排除的誤解。","textEn":"Compare closed and unclosed hypothetical phase-space paths. Retain each reference and uncertainty; reject the misconception: Entanglement at any intermediate time proves a completed gate.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就激光糾纏與閉合軌跡的「運動介導的糾纏」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for motion-mediated entanglement in laser entanglement and closed paths?","options":["只要任意時刻有糾纏就代表閘完成。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較閉合與未閉合假想相空間軌跡。"],"optionsEn":["Entanglement at any intermediate time proves a completed gate.","Equal case averages rule out spatial, temporal and model errors.","Compare closed and unclosed hypothetical phase-space paths."],"answer":2,"explanation":"兩離子控制需在閘結束後避免殘留態與運動糾纏，否則動作資訊成為噪聲。 比較閉合與未閉合假想相空間軌跡。","explanationEn":"Entangling control should avoid residual state-motion entanglement after a gate, or motion retains error-producing information. Compare closed and unclosed hypothetical phase-space paths."}},{"id":"v11-ionq-forte-v11-07","order":3,"sequence":7,"title":"連通性與排程：架構分析","titleEn":"Connectivity and scheduling: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-06"],"objective":"針對全連通與共享光路提出可反駁的連通性與排程模型與驗證紀錄。","objectiveEn":"Produce a falsifiable connectivity and scheduling model and evidence record for connectivity and shared optics.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識全連通與共享光路。邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。 建立連通性與排程的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。對相同閘集合比較串行及資源受限排程。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify connectivity and shared optics in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling. Draw the inputs, states, outputs and boundaries of connectivity and scheduling, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare serial and resource-limited schedules for the same gate set. Record units, undisclosed parameters and model breakdown conditions.","observation":"對相同閘集合比較串行及資源受限排程。","observationEn":"Compare serial and resource-limited schedules for the same gate set.","failure":"常見誤判：全連通等同零延遲及無限並行。","failureEn":"Common misconception: All-to-all connectivity means zero latency and unlimited parallelism.","check":"提交全連通與共享光路的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for connectivity and shared optics.","knowledge":[{"id":"v11-ionq-forte-v11-07-k1","title":"連通性與排程","titleEn":"Connectivity and scheduling","text":"邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。 本課架構對應：全連通與共享光路","textEn":"Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling. Course architecture correspondence: Connectivity and shared optics","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-07-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對相同閘集合比較串行及資源受限排程。 應逐項保留基準與不確定度；全連通等同零延遲及無限並行。 是本單元要排除的誤解。","textEn":"Compare serial and resource-limited schedules for the same gate set. Retain each reference and uncertainty; reject the misconception: All-to-all connectivity means zero latency and unlimited parallelism.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就全連通與共享光路的「連通性與排程」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for connectivity and scheduling in connectivity and shared optics?","options":["邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。","全連通等同零延遲及無限並行。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling.","All-to-all connectivity means zero latency and unlimited parallelism.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。 對相同閘集合比較串行及資源受限排程。","explanationEn":"Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling. Compare serial and resource-limited schedules for the same gate set."}},{"id":"v11-ionq-forte-v11-08","order":4,"sequence":8,"title":"連通性與排程：證據驗證","titleEn":"Connectivity and scheduling: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-07"],"objective":"針對全連通與共享光路提出可反駁的連通性與排程模型與驗證紀錄。","objectiveEn":"Produce a falsifiable connectivity and scheduling model and evidence record for connectivity and shared optics.","instruction":"沿用前一步「連通性與排程」模型，檢查全連通與共享光路的兩個假想案例。對相同閘集合比較串行及資源受限排程。 先訂可接受誤差，再比較預測與獨立計算；區分邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous connectivity and scheduling model to inspect two hypothetical cases involving connectivity and shared optics. Compare serial and resource-limited schedules for the same gate set. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"對相同閘集合比較串行及資源受限排程。","observationEn":"Compare serial and resource-limited schedules for the same gate set.","failure":"常見誤判：全連通等同零延遲及無限並行。","failureEn":"Common misconception: All-to-all connectivity means zero latency and unlimited parallelism.","check":"提交全連通與共享光路的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for connectivity and shared optics.","knowledge":[{"id":"v11-ionq-forte-v11-08-k1","title":"連通性與排程","titleEn":"Connectivity and scheduling","text":"邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。 本課架構對應：全連通與共享光路","textEn":"Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling. Course architecture correspondence: Connectivity and shared optics","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-08-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"對相同閘集合比較串行及資源受限排程。 應逐項保留基準與不確定度；全連通等同零延遲及無限並行。 是本單元要排除的誤解。","textEn":"Compare serial and resource-limited schedules for the same gate set. Retain each reference and uncertainty; reject the misconception: All-to-all connectivity means zero latency and unlimited parallelism.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就全連通與共享光路的「連通性與排程」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for connectivity and scheduling in connectivity and shared optics?","options":["全連通等同零延遲及無限並行。","對相同閘集合比較串行及資源受限排程。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["All-to-all connectivity means zero latency and unlimited parallelism.","Compare serial and resource-limited schedules for the same gate set.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"邏輯全連通不保證所有閘能同時執行；光學通道與模態共享形成排程限制。 對相同閘集合比較串行及資源受限排程。","explanationEn":"Logical all-to-all connectivity does not imply unlimited parallel gates; shared optical channels and modes constrain scheduling. Compare serial and resource-limited schedules for the same gate set."}}]},{"id":"v11-ionq-forte-v11-stage3","order":3,"title":"獨立驗證與工程交接","titleEn":"Independent validation and engineering handoff","description":"在IonQ Forte 光學位址量子核心案例中比較重排與通道邊界與螢光與樣本分佈，各完成分析及驗證。","descriptionEn":"Analyze and validate rearrangement and channel boundaries and fluorescence and sample distributions within the IonQ Forte optically addressed quantum core case.","steps":[{"id":"v11-ionq-forte-v11-09","order":1,"sequence":9,"title":"線性鏈與QCCD比較：架構分析","titleEn":"Linear chains versus QCCD: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-08"],"objective":"針對重排與通道邊界提出可反駁的線性鏈與QCCD比較模型與驗證紀錄。","objectiveEn":"Produce a falsifiable linear chains versus qccd model and evidence record for rearrangement and channel boundaries.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識重排與通道邊界。Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。 建立線性鏈與QCCD比較的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。並排比較位址重設與離子搬運，標出各自公開支持的功能。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify rearrangement and channel boundaries in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD. Draw the inputs, states, outputs and boundaries of linear chains versus qccd, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare addressing reconfiguration/ion transport and label publicly supported functions. Record units, undisclosed parameters and model breakdown conditions.","observation":"並排比較位址重設與離子搬運，標出各自公開支持的功能。","observationEn":"Compare addressing reconfiguration/ion transport and label publicly supported functions.","failure":"常見誤判：Forte使用離子就必然採用H2的跑道搬運。","failureEn":"Common misconception: Using ions means Forte necessarily has H2 racetrack transport.","check":"提交重排與通道邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for rearrangement and channel boundaries.","knowledge":[{"id":"v11-ionq-forte-v11-09-k1","title":"線性鏈與QCCD比較","titleEn":"Linear chains versus QCCD","text":"Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。 本課架構對應：重排與通道邊界","textEn":"Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD. Course architecture correspondence: Rearrangement and channel boundaries","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-09-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"並排比較位址重設與離子搬運，標出各自公開支持的功能。 應逐項保留基準與不確定度；Forte使用離子就必然採用H2的跑道搬運。 是本單元要排除的誤解。","textEn":"Compare addressing reconfiguration/ion transport and label publicly supported functions. Retain each reference and uncertainty; reject the misconception: Using ions means Forte necessarily has H2 racetrack transport.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就重排與通道邊界的「線性鏈與QCCD比較」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for linear chains versus qccd in rearrangement and channel boundaries?","options":["Forte使用離子就必然採用H2的跑道搬運。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。"],"optionsEn":["Using ions means Forte necessarily has H2 racetrack transport.","Equal case averages rule out spatial, temporal and model errors.","Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD."],"answer":2,"explanation":"Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。 並排比較位址重設與離子搬運，標出各自公開支持的功能。","explanationEn":"Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD. Compare addressing reconfiguration/ion transport and label publicly supported functions."}},{"id":"v11-ionq-forte-v11-10","order":2,"sequence":10,"title":"線性鏈與QCCD比較：證據驗證","titleEn":"Linear chains versus QCCD: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-09"],"objective":"針對重排與通道邊界提出可反駁的線性鏈與QCCD比較模型與驗證紀錄。","objectiveEn":"Produce a falsifiable linear chains versus qccd model and evidence record for rearrangement and channel boundaries.","instruction":"沿用前一步「線性鏈與QCCD比較」模型，檢查重排與通道邊界的兩個假想案例。並排比較位址重設與離子搬運，標出各自公開支持的功能。 先訂可接受誤差，再比較預測與獨立計算；區分Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous linear chains versus qccd model to inspect two hypothetical cases involving rearrangement and channel boundaries. Compare addressing reconfiguration/ion transport and label publicly supported functions. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"並排比較位址重設與離子搬運，標出各自公開支持的功能。","observationEn":"Compare addressing reconfiguration/ion transport and label publicly supported functions.","failure":"常見誤判：Forte使用離子就必然採用H2的跑道搬運。","failureEn":"Common misconception: Using ions means Forte necessarily has H2 racetrack transport.","check":"提交重排與通道邊界的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for rearrangement and channel boundaries.","knowledge":[{"id":"v11-ionq-forte-v11-10-k1","title":"線性鏈與QCCD比較","titleEn":"Linear chains versus QCCD","text":"Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。 本課架構對應：重排與通道邊界","textEn":"Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD. Course architecture correspondence: Rearrangement and channel boundaries","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-10-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"並排比較位址重設與離子搬運，標出各自公開支持的功能。 應逐項保留基準與不確定度；Forte使用離子就必然採用H2的跑道搬運。 是本單元要排除的誤解。","textEn":"Compare addressing reconfiguration/ion transport and label publicly supported functions. Retain each reference and uncertainty; reject the misconception: Using ions means Forte necessarily has H2 racetrack transport.","sourceIds":["v11x-forte","v11x-iontech"]}],"quiz":{"question":"就重排與通道邊界的「線性鏈與QCCD比較」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for linear chains versus qccd in rearrangement and channel boundaries?","options":["並排比較位址重設與離子搬運，標出各自公開支持的功能。","Forte使用離子就必然採用H2的跑道搬運。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["Compare addressing reconfiguration/ion transport and label publicly supported functions.","Using ions means Forte necessarily has H2 racetrack transport.","Equal case averages rule out spatial, temporal and model errors."],"answer":0,"explanation":"Forte公開架構重點為光學可設定離子鏈；QCCD搬運是可比較的另一架構，不宣稱Forte實作跑道QCCD。 並排比較位址重設與離子搬運，標出各自公開支持的功能。","explanationEn":"Forte emphasizes optically configurable ion chains; QCCD transport is a contrasting architecture, not a claim that Forte implements a racetrack QCCD. Compare addressing reconfiguration/ion transport and label publicly supported functions."}},{"id":"v11-ionq-forte-v11-11","order":3,"sequence":11,"title":"螢光讀出與重用：架構分析","titleEn":"Fluorescence readout and reuse: architecture analysis","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-10"],"objective":"針對螢光與樣本分佈提出可反駁的螢光讀出與重用模型與驗證紀錄。","objectiveEn":"Produce a falsifiable fluorescence readout and reuse model and evidence record for fluorescence and sample distributions.","instruction":"在「IonQ Forte 光學位址量子核心」的師傅示意與公開來源中，先辨識螢光與樣本分佈。讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。 建立螢光讀出與重用的輸入、狀態、輸出及邊界圖；本課重點是聲光偏轉選址與線性離子鏈。用本課假想算例建立基準，再只改一個相關假設，預測哪個輸出先變。比較兩個計數分佈的指派錯誤並記錄讀出時窗。 記錄單位、未公開參數及模型失效條件。","instructionEn":"Identify fluorescence and sample distributions in the mentor diagram and primary sources for IonQ Forte optically addressed quantum core. Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement. Draw the inputs, states, outputs and boundaries of fluorescence readout and reuse, focusing on acousto-optic addressing and linear ion chains. Establish a baseline with the hypothetical worked example, change one relevant assumption and predict the first affected output. Compare assignment errors for two count distributions and record the readout window. Record units, undisclosed parameters and model breakdown conditions.","observation":"比較兩個計數分佈的指派錯誤並記錄讀出時窗。","observationEn":"Compare assignment errors for two count distributions and record the readout window.","failure":"常見誤判：較多光子必然改善整個電路且沒有反作用。","failureEn":"Common misconception: More photons always improve the full circuit without back-action.","check":"提交螢光與樣本分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for fluorescence and sample distributions.","knowledge":[{"id":"v11-ionq-forte-v11-11-k1","title":"螢光讀出與重用","titleEn":"Fluorescence readout and reuse","text":"讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。 本課架構對應：螢光與樣本分佈","textEn":"Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement. Course architecture correspondence: Fluorescence and sample distributions","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-11-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩個計數分佈的指派錯誤並記錄讀出時窗。 應逐項保留基準與不確定度；較多光子必然改善整個電路且沒有反作用。 是本單元要排除的誤解。","textEn":"Compare assignment errors for two count distributions and record the readout window. Retain each reference and uncertainty; reject the misconception: More photons always improve the full circuit without back-action.","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-11-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 42 個獨立且相同錯誤率 p=0.0010 的事件，無錯誤機率 (1−p)^42=0.958850。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 42 independent events with equal p=0.0010: no-error probability (1−p)^42=0.958850. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-forte","v11x-iontech"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就螢光與樣本分佈的「螢光讀出與重用」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for fluorescence readout and reuse in fluorescence and sample distributions?","options":["較多光子必然改善整個電路且沒有反作用。","讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。"],"optionsEn":["More photons always improve the full circuit without back-action.","Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement.","Equal case averages rule out spatial, temporal and model errors."],"answer":1,"explanation":"讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。 比較兩個計數分佈的指派錯誤並記錄讀出時窗。","explanationEn":"Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement. Compare assignment errors for two count distributions and record the readout window."}},{"id":"v11-ionq-forte-v11-12","order":4,"sequence":12,"title":"螢光讀出與重用：證據驗證","titleEn":"Fluorescence readout and reuse: evidence validation","estimatedMinutes":35,"simulationOnly":true,"sourceIds":["v11x-forte","v11x-iontech"],"prerequisiteIds":["v11-ionq-forte-v11-11"],"objective":"針對螢光與樣本分佈提出可反駁的螢光讀出與重用模型與驗證紀錄。","objectiveEn":"Produce a falsifiable fluorescence readout and reuse model and evidence record for fluorescence and sample distributions.","instruction":"沿用前一步「螢光讀出與重用」模型，檢查螢光與樣本分佈的兩個假想案例。比較兩個計數分佈的指派錯誤並記錄讀出時窗。 先訂可接受誤差，再比較預測與獨立計算；區分讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。與另一個可能造成相同輸出的機制。保存輸入、殘差、不確定度及採信／保留理由。缺少公開資料就標示尚未驗證，不補造產品數字。","instructionEn":"Use the previous fluorescence readout and reuse model to inspect two hypothetical cases involving fluorescence and sample distributions. Compare assignment errors for two count distributions and record the readout window. Set acceptable error before comparing predictions with an independent calculation. Distinguish \"Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement.\" from an alternative cause with similar output. Save inputs, residuals, uncertainty and accept/hold reasoning. Mark absent public evidence as unverified rather than inventing product values.","observation":"比較兩個計數分佈的指派錯誤並記錄讀出時窗。","observationEn":"Compare assignment errors for two count distributions and record the readout window.","failure":"常見誤判：較多光子必然改善整個電路且沒有反作用。","failureEn":"Common misconception: More photons always improve the full circuit without back-action.","check":"提交螢光與樣本分佈的系統邊界圖、兩案例計算、單位／不確定度表及一項能區分競爭機制的證據。","checkEn":"Submit a boundary diagram, two-case calculation, units/uncertainty table and discriminating evidence for fluorescence and sample distributions.","knowledge":[{"id":"v11-ionq-forte-v11-12-k1","title":"螢光讀出與重用","titleEn":"Fluorescence readout and reuse","text":"讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。 本課架構對應：螢光與樣本分佈","textEn":"Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement. Course architecture correspondence: Fluorescence and sample distributions","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-12-k2","title":"獨立驗證與失效邊界","titleEn":"Independent validation and breakdown boundary","text":"比較兩個計數分佈的指派錯誤並記錄讀出時窗。 應逐項保留基準與不確定度；較多光子必然改善整個電路且沒有反作用。 是本單元要排除的誤解。","textEn":"Compare assignment errors for two count distributions and record the readout window. Retain each reference and uncertainty; reject the misconception: More photons always improve the full circuit without back-action.","sourceIds":["v11x-forte","v11x-iontech"]},{"id":"v11-ionq-forte-v11-12-k3","title":"原創假想量化練習","titleEn":"Original hypothetical quantitative exercise","text":"假設 42 個獨立且相同錯誤率 p=0.0010 的事件，無錯誤機率 (1−p)^42=0.958850。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 42 independent events with equal p=0.0010: no-error probability (1−p)^42=0.958850. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","sourceIds":["v11x-forte","v11x-iontech"],"authorship":"original-hypothetical-exercise"}],"quiz":{"question":"就螢光與樣本分佈的「螢光讀出與重用」，哪個推論或驗證成立？","questionEn":"Which inference or check is justified for fluorescence readout and reuse in fluorescence and sample distributions?","options":["較多光子必然改善整個電路且沒有反作用。","兩個案例的平均相同，就足以排除空間、時間及模型誤差。","比較兩個計數分佈的指派錯誤並記錄讀出時窗。"],"optionsEn":["More photons always improve the full circuit without back-action.","Equal case averages rule out spatial, temporal and model errors.","Compare assignment errors for two count distributions and record the readout window."],"answer":2,"explanation":"讀出由散射光子統計決定；重置、旁觀者位元及量測時間影響中途量測。 比較兩個計數分佈的指派錯誤並記錄讀出時窗。","explanationEn":"Readout uses photon-count statistics; reset, spectator qubits and duration affect mid-circuit measurement. Compare assignment errors for two count distributions and record the readout window."}}]}],"summary":"以聲光偏轉選址與線性離子鏈解析IonQ Forte 光學位址量子核心：六個原理與架構單元、十二項可保存的分析及驗證作業，附假想量化例、來源及衍生工程比較。","summaryEn":"Explore IonQ Forte optically addressed quantum core through acousto-optic addressing and linear ion chains: six principle/architecture units and twelve saved analysis/validation tasks, with an assumed numerical example, primary sources and related engineering comparisons.","scope":"依公開研究與裝置資料編寫的離線模型、編譯及證據判讀。不是實機組裝、雷射或低溫作業SOP；假想算例不代表廠商精度、量子優勢或容錯能力。研發宣稱與已驗證觀測分開標示。","scopeEn":"Offline models, compilation and evidence interpretation from public research/device sources. Not hardware assembly, laser/cryogenic SOPs; assumed examples are not vendor fidelity, advantage or fault tolerance. Development claims and demonstrated observations remain distinct.","workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"假設 42 個獨立且相同錯誤率 p=0.0010 的事件，無錯誤機率 (1−p)^42=0.958850。此簡化不含相干、相關、洩漏與讀出錯誤，不能預測完整量子電路或邏輯精度。","textEn":"Assume 42 independent events with equal p=0.0010: no-error probability (1−p)^42=0.958850. Coherent, correlated, leakage and readout errors are omitted; this does not predict full-circuit/logical fidelity.","assumptions":"數值是本課自行設定的假設，不代表實機量測、產品額定或操作參數；改變模型邊界後必須重算。","assumptionsEn":"Inputs are independently selected assumptions, not measured hardware, ratings or operating parameters; recalculate after boundary changes.","sourceScope":"原創數值練習；來源支援公開架構及領域原理，不宣稱來源提供這組假想數據。","sourceScopeEn":"Original numerical exercise; sources support public architecture and principles, not these assumed measurements."},"diagram":{"type":"optics","labels":["Forte離子鏈模態","AOD光束選址","激光糾纏與閉合軌跡","全連通與共享光路","重排與通道邊界","螢光與樣本分佈"],"labelsEn":["Forte ion-chain modes","AOD beam addressing","Laser entanglement and closed paths","Connectivity and shared optics","Rearrangement and channel boundaries","Fluorescence and sample distributions"],"original":true,"notToScale":true},"vendorHints":[{"name":"IonQ","nameEn":"IonQ","url":"https://www.ionq.com/quantum-systems/forte","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-forte"]},{"name":"IonQ","nameEn":"IonQ","url":"https://www.ionq.com/technology","role":"官方工程或研究資料；不表示背書、授課或本平臺能訪問其設備。","roleEn":"Official engineering/research reference; no endorsement, teaching partnership or hardware access is implied.","sourceIds":["v11x-iontech"]}],"architectureNodes":[["位址雷射","Addressing lasers"],["離子與陷阱","Ions and trap"],["螢光讀出","Fluorescence readout"],["經典控制器","Classical controller"],["運動模態","Motional modes"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,0],[4,1]],"architectureFamily":"qpu","educationEdition":11,"enrichmentVersion":11}};
